import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class SolutionTest {
    public static void main(String[] args) {
        Solution.Submission a = new Solution.Submission("  s1 ", " First ", " owner-a ");
        Solution.Submission b = new Solution.Submission("s2", "Second", "owner-b");
        Solution.Submission c = new Solution.Submission("s3", "Third", "owner-a");
        eq("s1", a.getId());
        eq("First", a.getTitle());
        eq("owner-a", a.getOwnerId());

        List<Solution.Submission> input = new ArrayList<>(Arrays.asList(a, b, c));
        Map<String, String> aliases = new HashMap<>();
        aliases.put("alice", "owner-a");
        aliases.put("nobody", "missing-owner");

        List<Solution.Submission> matches = Solution.findSubmissions(input, aliases, "  alice  ");
        sameList(Arrays.asList(a, c), matches);
        unmodifiable(matches);
        input.clear();
        sameList(Arrays.asList(a, c), matches);

        input.addAll(Arrays.asList(a, b, c));
        sameList(Arrays.asList(b), Solution.findSubmissions(input, aliases, "owner-b"));
        sameList(Arrays.asList(a, b, c), Solution.findSubmissions(input, aliases, null));
        sameList(Arrays.asList(a, b, c), Solution.findSubmissions(input, aliases, " \t "));
        sameList(new ArrayList<Solution.Submission>(), Solution.findSubmissions(input, aliases, "unknown"));
        sameList(new ArrayList<Solution.Submission>(), Solution.findSubmissions(input, aliases, "nobody"));

        List<Solution.Submission> empty = Solution.findSubmissions(new ArrayList<Solution.Submission>(),
                new HashMap<String, String>(), "user");
        sameList(new ArrayList<Solution.Submission>(), empty);
        unmodifiable(empty);

        bad(() -> new Solution.Submission(null, "title", "owner"));
        bad(() -> new Solution.Submission(" ", "title", "owner"));
        bad(() -> new Solution.Submission("id", null, "owner"));
        bad(() -> new Solution.Submission("id", "\t", "owner"));
        bad(() -> new Solution.Submission("id", "title", null));
        bad(() -> new Solution.Submission("id", "title", "\r\n"));

        bad(() -> Solution.findSubmissions(null, aliases, "alice"));
        bad(() -> Solution.findSubmissions(input, null, "alice"));
        bad(() -> Solution.findSubmissions(Arrays.asList(a, null), aliases, null));
        Map<String, String> badAliasKey = new HashMap<>();
        badAliasKey.put(" ", "owner-a");
        bad(() -> Solution.findSubmissions(input, badAliasKey, null));
        Map<String, String> badAliasValue = new HashMap<>();
        badAliasValue.put("alice", "\t");
        bad(() -> Solution.findSubmissions(input, badAliasValue, "alice"));
        Map<String, String> nullAlias = new HashMap<>();
        nullAlias.put(null, "owner-a");
        bad(() -> Solution.findSubmissions(input, nullAlias, "alice"));
    }

    private static void sameList(List<Solution.Submission> expected, List<Solution.Submission> actual) {
        if (expected.size() != actual.size()) throw new AssertionError("Wrong size");
        for (int i = 0; i < expected.size(); i++) {
            if (expected.get(i) != actual.get(i)) throw new AssertionError("Wrong submission at " + i);
        }
    }

    private static void eq(Object expected, Object actual) {
        if (!expected.equals(actual)) throw new AssertionError("Expected " + expected + " but got " + actual);
    }

    private static void unmodifiable(List<Solution.Submission> list) {
        try {
            list.add(new Solution.Submission("x", "x", "x"));
            throw new AssertionError("List was modifiable");
        } catch (UnsupportedOperationException expected) {
        }
    }

    private static void bad(Runnable action) {
        try {
            action.run();
            throw new AssertionError("Expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        }
    }
}

